B.Ol=s(["af","am","ar","as","az","be","bg","bn","bo","bs","ca","cs","cy","da","de","el","en","es","et","eu","fa","fi","fil","fr","ga","gl","gsw","gu","he","hi","hr","hu","hy","id","is","it","ja","ka","kk","km","kn","ko","ky","lo","lt","lv","mk","ml","mn","mr","ms","my","nb","ne","nl","no","or","pa","pl","ps","pt","ro","ru","si","sk","sl","sq","sr","sv","sw","ta","te","th","tl","tr","ug","uk","ur","uz","vi","zh","zu"],t.s)
B.baC=s(["From a balanced perspective...","A clear illustration of this is...","Rather than rushing to conclusions..."],t.s)
B.bo2=new A.K2(["D\xe9veloppez votre rigueur intellectuelle, votre ma\xeetrise de l\u2019anglais et votre discipline personnelle dans un cadre exigeant et bienveillant.","S\u2019\xc9LEVER INDIVIDUELLEMENT",B.Ev,"Savoir, Spiritualit\xe9 & Esprit Critique"])
B.bnZ=new A.K2(["Participez \xe0 des d\xe9bats vocaux \xe9valu\xe9s sur une grille transparente de 100 points \u2014 centr\xe9e uniquement sur la qualit\xe9 du raisonnement, jamais sur votre accent ou origine.","D\xc9BATTRE AVEC \xc9QUIT\xc9",B.wa,"Yitt\xe9 Face-\xe0-Face & Quiz Arena"])
